module browserjs

import html

fn test_public_webgl_context_prototypes_apply_source_receiver_before_argument_checks() {
	$if !darwin {
		return
	}
	mut document := html.parse_document('<canvas></canvas>')
	mut host := CanvasWebGLHost.create(document)
	mut runtime := Runtime.create()
	defer { runtime.close() }
	host.install(mut runtime)!
	runtime.evaluate_host('const __canvases=Object.create(null);function __canvasFor(s){return __canvases[s.bridgeKey]||(__canvases[s.bridgeKey]={state:s});}function __canvasDimension(s,key){return s[key];}function __element(s){return s.element||(s.element={state:s});}')!
	runtime.evaluate_host(webgl_bootstrap())!
	assert runtime.evaluate_host(r'(function(){for(const operation of [WebGL2RenderingContext.prototype.clearColor,WebGL2RenderingContext.prototype.getExtension,Object.getOwnPropertyDescriptor(WebGL2RenderingContext.prototype,"canvas").get]){if(Object.prototype.hasOwnProperty.call(operation,"prototype"))return false;try{new operation();return false}catch(error){if(!(error instanceof TypeError))return false}}return true})()')! == 'true'
	assert runtime.evaluate_host(r'(function(){const descriptor=Object.getOwnPropertyDescriptor(WebGL2RenderingContext.prototype,"clearColor"),constant=Object.getOwnPropertyDescriptor(WebGL2RenderingContext.prototype,"COLOR_BUFFER_BIT"),globalConstant=Object.getOwnPropertyDescriptor(WebGL2RenderingContext,"COLOR_BUFFER_BIT");return typeof WebGLRenderingContext.prototype.clear==="function"&&descriptor.enumerable&&descriptor.configurable&&descriptor.writable&&descriptor.value.name==="clearColor"&&descriptor.value.length===4&&constant.enumerable&&!constant.configurable&&!constant.writable&&globalConstant.enumerable&&!globalConstant.configurable&&!globalConstant.writable&&globalConstant.value===0x4000&&Object.getPrototypeOf(WebGLRenderingContext.prototype)===Object.prototype&&Object.getPrototypeOf(WebGL2RenderingContext.prototype)===Object.prototype&&WebGL2RenderingContext.prototype.bufferData.length===3&&WebGL2RenderingContext.prototype.getExtension.length===1})()')! == 'true'
	runtime.evaluate_host(r'const aState={bridgeKey:"__created_proto_a",width:2,height:2},bState={bridgeKey:"__created_proto_b",width:2,height:2},oneState={bridgeKey:"__created_proto_one",width:2,height:2},a=__webglContext(aState,"webgl2",{preserveDrawingBuffer:true}),b=__webglContext(bState,"webgl2",{preserveDrawingBuffer:true}),one=__webglContext(oneState,"webgl",{preserveDrawingBuffer:true});')!
	assert runtime.evaluate_host(r'(function(){return a.clear===b.clear&&a.clear===WebGL2RenderingContext.prototype.clear&&a.getExtension===b.getExtension&&!Object.prototype.hasOwnProperty.call(a,"clear")&&!Object.prototype.hasOwnProperty.call(a,"COLOR_BUFFER_BIT")&&!Object.prototype.hasOwnProperty.call(a,"canvas")&&Object.prototype.toString.call(a)==="[object WebGL2RenderingContext]"&&Object.prototype.toString.call(one)==="[object WebGLRenderingContext]"&&a.canvas===aState.element&&a.drawingBufferWidth===2&&a.drawingBufferHeight===2})()')! == 'true'
	assert runtime.evaluate_host(r'(function(){let converted=0;const number={valueOf(){converted++;throw "converted"}},name={toString(){converted++;throw "string"}};const calls=[()=>a.clearColor.call({},number,0,0,1),()=>a.clear.call({}),()=>a.getExtension.call({},name),()=>a.clearColor.call(Object.create(WebGL2RenderingContext.prototype),number,0,0,1),()=>a.clear.call(one,0)];if(!calls.every(call=>{try{call();return false}catch(error){return error instanceof TypeError&&error.message==="Not an object of type WebGL2RenderingContext"}})||converted!==0)return false;try{WebGLRenderingContext.prototype.clear.call(a,0);return false}catch(error){if(error.message!=="Not an object of type WebGLRenderingContext")return false}for(const [call,message] of [[()=>a.clear(),"clear() needs one argument"],[()=>a.clearColor(1),"clearColor() needs 4 arguments"],[()=>a.getExtension(),"getExtension() needs one argument"]]){try{call();return false}catch(error){if(error.message!==message)return false}}return a.getError()===a.NO_ERROR&&b.getError()===b.NO_ERROR})()')! == 'true'
	assert runtime.evaluate_host(r'(function(){a.clearColor(1,0,0,1);a.clear(a.COLOR_BUFFER_BIT);b.clearColor(0,0,1,1);b.clear(b.COLOR_BUFFER_BIT);a.clearColor.call(b,0,1,0,1);a.clear.call(b,a.COLOR_BUFFER_BIT);const red=new Uint8Array(4),green=new Uint8Array(4);b.readPixels.call(a,0,0,1,1,a.RGBA,a.UNSIGNED_BYTE,red);a.readPixels.call(b,0,0,1,1,b.RGBA,b.UNSIGNED_BYTE,green);return red.join(",")==="255,0,0,255"&&green.join(",")==="0,255,0,255"&&a.getError()===a.NO_ERROR&&b.getError()===b.NO_ERROR})()')! == 'true'
	assert runtime.evaluate_host(r'(function(){const getter=Object.getOwnPropertyDescriptor(WebGL2RenderingContext.prototype,"canvas").get;if(getter.call(b)!==bState.element)return false;try{getter.call({});return false}catch(error){if(error.message!=="Not an object of type WebGL2RenderingContext")return false}try{(function(){"use strict";a.canvas={}})();return false}catch(error){if(!(error instanceof TypeError))return false}for(const Constructor of [WebGLRenderingContext,WebGL2RenderingContext]){if(Constructor.length!==0||Object.getOwnPropertyDescriptor(Constructor,"prototype").writable)return false;try{new Constructor();return false}catch(error){if(error.message!==Constructor.name+" is not a constructor")return false}try{Constructor();return false}catch(error){if(error.message!==Constructor.name+" constructor must be called with \u0027new\u0027")return false}}return true})()')! == 'true'
	assert runtime.evaluate_host(r'(function(){const Constructor=WebGL2RenderingContext;globalThis.WebGL2RenderingContext=function AuthorConstructor(){};const context=__webglContext({bridgeKey:"__created_proto_after_global_replacement",width:2,height:2},"webgl2",null);return context instanceof Constructor&&Object.getPrototypeOf(context)===Constructor.prototype&&context.drawingBufferWidth===2&&context.getError()===context.NO_ERROR})()')! == 'true'
}
